from taf.ul.sbts.energy_saving.objects.power_group import PowerGroup


class PSGRPManager(PowerGroup):
    """4G LTE Power Saving Group"""

    @property
    def group_type(self) -> str:
        return "PSGRP"

    @property
    def bts_type(self) -> str:
        return "LNBTS"

    @property
    def cell_id_param(self) -> str:
        return "lnCelId"

    @property
    def cell_type(self) -> str:
        return "LNCEL"

    def get_recommended_parameters(self):
        return {
            "lbpsSOMethod": "Cell Switch Off",
            "lbpsLastCellSOEnabled": True,
            "lbpsMonWinForCellSOff": 60,
            "lbpsMonWinForCellSOn": 30
        }
